static class V11Checks {
 public static void AnimationUI(Application app,string path){var log=new List<string>();Action<bool,string> check=(ok,s)=>{log.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);if(!ok)throw new Exception(s);};app.ShutdownMode=ShutdownMode.OnExplicitShutdown;app.Dispatcher.BeginInvoke((Action)(async()=>{try{var watch=System.Diagnostics.Stopwatch.StartNew();var w=new FailureWindow("运行失败 · 暗域吞噬");int frames=0;EventHandler rendering=(s,e)=>frames++;CompositionTarget.Rendering+=rendering;w.Show();await Task.Delay(2150);check(w.IsVisible&&w.AnimatedOpacity>.95,"Full-screen animation fades in and remains visible");var matrix=PresentationSource.FromVisual(w).CompositionTarget.TransformToDevice;var bounds=System.Windows.Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(w).Handle).Bounds;check(Math.Abs(w.ActualWidth*matrix.M11-bounds.Width)<3&&Math.Abs(w.ActualHeight*matrix.M22-bounds.Height)<3,"Animation covers complete current monitor including taskbar");Theme.Capture((FrameworkElement)w.Content,Path.Combine(Path.GetDirectoryName(path),"处决动画-全屏验证.png"),matrix.M11*96);await Task.Delay(2600);CompositionTarget.Rendering-=rendering;check(!w.IsVisible&&watch.Elapsed.TotalSeconds>=4.3,"Animation automatically fades out and releases window");check(frames>=30,"Rendering remained active: "+frames+" composition frames");var escaped=new FailureWindow("编译失败 · 封印反噬",true);escaped.Show();await Task.Delay(700);var key=new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(escaped),0,Key.Escape){RoutedEvent=Keyboard.KeyDownEvent};escaped.RaiseEvent(key);for(int retry=0;retry<30&&escaped.IsVisible;retry++)await Task.Delay(50);check(key.Handled&&!escaped.IsVisible,"Esc key route triggers fade-out and closes early");log.Add("ALL ANIMATION CHECKS PASSED");File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);app.Shutdown();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);app.Shutdown(1);}}));app.Run();}
 public static void Smoke(string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"smoke-"+Guid.NewGuid().ToString("N"));var log=new List<string>();bool failed=false;foreach(int n in new[]{1,4,10,13,18,24,32,33,49,50})foreach(int seed in new[]{202611,456789}){var l=ChallengeBank.Levels[n-1];var e=Engine.Judge(l.Problem,l.Problem.Reference,seed,CancellationToken.None,(a,b)=>{});bool ok=e.Compiled&&e.Score>=99.9&&e.Cases.All(c=>c.Passed);log.Add((ok?"PASS ":"FAIL ")+"final strengthened level "+n+" seed "+seed+" score "+e.Score);if(!ok){failed=true;log.Add(Engine.Report(e));}File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);}log.Add(failed?"FAILED":"ALL FINAL SMOKE CHECKS PASSED");File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);Environment.ExitCode=failed?1:0;}
 static T Field<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}
 public static void Run(string path){Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"v11-test-"+Guid.NewGuid().ToString("N"));var lines=new List<string>();int failed=0;Action<bool,string> check=(ok,n)=>{lines.Add((ok?"PASS ":"FAIL ")+n);if(!ok)failed++;File.WriteAllLines(path,lines.ToArray(),Encoding.UTF8);};
  check(ChallengeBank.Levels.Count==50&&ChallengeBank.Levels.Select(l=>l.Number).SequenceEqual(Enumerable.Range(1,50)),"50 sequential levels");check(ChallengeBank.Levels.First().Seconds==180&&ChallengeBank.Levels.Last().Seconds==600&&ChallengeBank.Levels.All(l=>l.Seconds>=180&&l.Seconds<=600),"Countdown spans 3 to 10 minutes");check(ChallengeBank.Levels.Select(l=>l.Seconds).SequenceEqual(ChallengeBank.Levels.Select(l=>l.Seconds).OrderBy(x=>x)),"Countdown increases monotonically");check(ChallengeBank.Levels.All(l=>l.Learning.Length>90&&l.Problem.Statement.Length>25),"Every level has a detailed independent lesson and IO contract");
  foreach(var l in ChallengeBank.Levels)foreach(int seed in new[]{202611,456789}){var ev=Engine.Judge(l.Problem,l.Problem.Reference,seed,CancellationToken.None,(a,b)=>{});bool ok=ev.Compiled&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Passed)&&ev.Score>=99.9;check(ok,"Challenge "+l.Number+" "+l.Problem.Title+" seed "+seed+" score "+ev.Score);if(!ok){lines.Add(Engine.Report(ev));File.WriteAllLines(path,lines.ToArray(),Encoding.UTF8);}}
  foreach(var p in Bank.All()){var ev=Engine.Judge(p,p.Reference,202611,CancellationToken.None,(a,b)=>{});check(ev.Compiled&&ev.Cases.Count==28&&ev.Cases.All(c=>c.Passed)&&ev.Score>=99.9,"Original bank regression "+p.Id+" score "+ev.Score);}
  string[] diagnostics={"answer.c:4: error: ';' expected","answer.c:6: error: 'x' undeclared","answer.c:7: error: undefined symbol 'hello'","answer.c:9: error: ')' expected","answer.c:2: error: incompatible types","warning: implicit declaration of function 'foo'","error: redefinition of 'x'","error: division by zero","unknown compiler diagnostic text"};foreach(string raw in diagnostics){string translated=Diagnostics.Explain(raw);check(translated.Contains(raw)&&translated.Contains("中文解释："),"Original preserved and Chinese added: "+raw);}check(Diagnostics.Translate(diagnostics[0]).Contains("分号")&&Diagnostics.Translate(diagnostics[0]).Contains("第 4 行"),"Semicolon translation includes line number");
  var gate=GateEvaluation(90);check(!ChallengeProgress.Qualifies(gate),"Exactly 90 cannot pass");gate.Score=90.1;check(ChallengeProgress.Qualifies(gate),"Strictly above 90 can pass");gate.Cases[0].Run.Failure="crash";check(!ChallengeProgress.Qualifies(gate)&&FailureWindow.ShouldPlay(gate),"Runtime failure rejects pass and triggers animation");gate=GateEvaluation(59.9);check(FailureWindow.ShouldPlay(gate),"Below 60 triggers failure");gate.Score=60;check(!FailureWindow.ShouldPlay(gate),"Exactly 60 does not trigger low-score failure");gate.Compiled=false;check(FailureWindow.ShouldPlay(gate),"Compile failure triggers animation");
  var state=new ChallengeProgress(Path.Combine(Engine.DataRoot,"gate-check"));check(state.Unlocked==1&&!state.Passed(1),"Fresh state unlocks only level 1");state.Record(1,GateEvaluation(90));check(state.Unlocked==1,"90 cannot unlock next");state.Record(1,GateEvaluation(90.1));check(state.Unlocked==2&&state.Passed(1),"Passing unlocks only next level");bool blocked=false;try{state.Begin(3,180);}catch(InvalidOperationException){blocked=true;}check(blocked,"Starting locked level blocked in model");state.SaveDraft(2,"own code");state.Begin(2,188);DateTime before=state.Deadline;state.Extend(TimeSpan.FromSeconds(2));var restored=new ChallengeProgress(Path.Combine(Engine.DataRoot,"gate-check"));check(restored.Unlocked==2&&restored.AttemptLevel==2&&restored.Deadline>before&&restored.Draft(2)=="own code","Progress, draft and absolute deadline survive reopening");restored.End();check(new ChallengeProgress(Path.Combine(Engine.DataRoot,"gate-check")).AttemptLevel==0,"Ended attempt clears persisted deadline");
  var t=ChallengeBank.Tests(150,12);check(t.Select(c=>c.Input).SequenceEqual(ChallengeBank.Tests(150,12).Select(c=>c.Input))&&!t.Select(c=>c.Input).SequenceEqual(ChallengeBank.Tests(150,13).Select(c=>c.Input)),"Randomized project reproducibility and seed diversity");
  lines.Add("TOTAL "+lines.Count(x=>x.StartsWith("PASS ")||x.StartsWith("FAIL "))+" FAILED "+failed);File.WriteAllLines(path,lines.ToArray(),Encoding.UTF8);Environment.ExitCode=failed==0?0:1;
 }
 static Evaluation GateEvaluation(double score){var e=new Evaluation{Compiled=true,Score=score};for(int i=0;i<28;i++)e.Cases.Add(new CaseResult{Run=new Execution(),Passed=true});return e;}
 public static void RunUI(Application app,string path){var log=new List<string>();Action<bool,string> check=(ok,s)=>{log.Add((ok?"PASS ":"FAIL ")+s);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);if(!ok)throw new Exception(s);};Engine.DataRoot=Path.Combine(Path.GetDirectoryName(Path.GetFullPath(path)),"v11-ui-"+Guid.NewGuid().ToString("N"));var game=new ChallengeWindow(true);game.ContentRendered+=async(s,e)=>{try{game.PreviewSize(1600,1000);await Task.Delay(120);check(!game.CanViewAnswer&&game.Editor.Text==""&&game.Editor.Input.IsReadOnly,"Blank manual editor and answer gated before start");game.Select(50);check(Field<ChallengeLevel>(game,"level").Number==1,"UI refuses locked level");game.StartForCheck();check(!game.Editor.Input.IsReadOnly&&Field<TextBlock>(game,"clock").Text.StartsWith("03:"),"Start enables editor and 3-minute countdown");
   var edit=game.Editor;edit.Input.Document.UndoStack.ClearAll();string[] changes={"int", " main", "(void)", " {", "\n    return 0;", "\n}"};foreach(string x in changes){edit.Input.Document.UndoStack.StartUndoGroup();edit.Input.Document.Insert(edit.Text.Length,x);edit.Input.Document.UndoStack.EndUndoGroup();}string full=edit.Text;check(edit.CanUndo&&!edit.CanRedo,"History button states follow document");for(int i=0;i<changes.Length;i++)edit.Undo();check(edit.Text==""&&edit.CanRedo&&!edit.CanUndo,"Six-step undo returns to blank");for(int i=0;i<changes.Length;i++)edit.Redo();check(edit.Text==full,"Six-step redo restores exact text");edit.Undo();edit.Input.Document.Insert(edit.Text.Length," NEW");check(!edit.CanRedo,"New edit discards redo branch");
   string original=edit.Text;ApplicationCommands.Paste.Execute(null,edit.Input);check(edit.Text==original&&!edit.Input.AllowDrop,"Paste command and dropping are blocked");
   int hitCount=0;foreach(double scale in new[]{1.0,1.5,2.0})foreach(int font in new[]{14,16,18,20,22,24}){edit.LayoutTransform=new ScaleTransform(scale,scale);edit.SetFontSize(font);edit.Text="int main(void) {\n    int value = 3; // 中文注释\n    return value;\n}\n";edit.Input.ScrollToHome();game.UpdateLayout();await Task.Delay(35);for(int line=1;line<=3;line++)foreach(int off in new[]{0,4,8,12}){int pos=edit.Input.Document.GetLineByNumber(line).Offset+off;Rect a=edit.Input.CharacterRect(pos),b=edit.Input.CharacterRect(pos+1);Point p=new Point(a.X+(b.X-a.X)*.2,a.Y+a.Height/2);check(edit.Input.Hit(p)==pos,"Challenge caret hit font "+font+" scale "+scale+" position "+pos);hitCount++;}}
   edit.LayoutTransform=Transform.Identity;edit.SetFontSize(16);check(hitCount==216,"Challenge editor coordinate coverage 216 points");edit.Text=ChallengeBank.Levels[0].Problem.Reference;await game.Judge();check(game.CanViewAnswer&&game.Progress.Unlocked==2&&Field<Button>(game,"next").IsEnabled,"Real GUI evaluation >90 unlocks next and review only after pass");game.Select(2);check(!game.CanViewAnswer&&edit.Text==""&&!edit.CanUndo,"Next level is blank, answer locked, no previous undo leakage");
   game.StartForCheck();edit.Text="int main(void){return ???;}";await game.Judge();check(Field<TextBox>(game,"output").Text.Contains("中文解释")&&!game.Progress.Passed(2)&&!Field<bool>(game,"active"),"Compiler failure adds Chinese diagnostics, ends attempt, no unlock");game.StartForCheck();game.ExpireForCheck();check(!Field<bool>(game,"active")&&Field<TextBlock>(game,"score").Text=="0"&&!game.Progress.Passed(2),"Countdown expiry fails without unlocking");
   foreach(double dpi in new[]{96.0,144.0,192.0}){game.PreviewSize(2560*96/dpi,1600*96/dpi);await Task.Delay(80);check(edit.Input.ActualWidth>350&&edit.Input.ActualHeight>180,"Challenge layout remains usable at 2.5K / "+dpi+" DPI");Theme.Capture((FrameworkElement)game.Content,Path.Combine(Path.GetDirectoryName(path),"闯关界面-"+dpi+"dpi.png"),dpi);}game.PreviewSize(1600,1000);
   var fail=new FailureWindow("编译失败 · 封印反噬",true){Owner=game};fail.Show();await Task.Delay(2150);Theme.Capture((FrameworkElement)fail.Content,Path.Combine(Path.GetDirectoryName(path),"失败动画预览.png"));check(fail.IsVisible&&FailureWindow.DurationSeconds==4.4,"Detailed embedded artwork and particles animate for 4.4s");fail.FadeOut();await Task.Delay(550);check(!fail.IsVisible,"Failure animation fades and releases window");
   log.Add("ALL V11 UI CHECKS PASSED");File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);game.Close();}catch(Exception ex){log.Add("FAIL "+ex);File.WriteAllLines(path,log.ToArray(),Encoding.UTF8);app.Shutdown(1);}};app.Run(game);}
}
